mapper.select:
SELECT COUNT(*)
  FROM sw_master
 WHERE 1=1
   AND delyn='N'

   AND itemdcd = #{itemdcd}


   AND apart LIKE CONCAT('%',#{apart},'%')


   AND acorpcd = #{acorpcd}


   AND astate = #{astate}


   AND lgubun = #{lgubun}


   AND swno LIKE CONCAT('%',#{swno},'%')

SELECT A.swno AS swno, D.shortnm AS shortnm, A.itemdcd AS itemdcd, B.item4nm AS item4nm, A.ugubun AS ugubun, A.swnm AS swnm, A.aplace AS aplace, A.lqty AS lqty , A.lgubun AS lgubun, A.apart AS apart, A.auser AS auser, A.myear AS myear, C.statenm AS statenm, A.iyear AS iyear , A.lsdate AS lsdate, A.ledate AS ledate, A.rqty AS rqty FROM sw_master A, ats_item B, ats_state C, corpcode D WHERE A.delyn='N' AND B.item2cd = '99' AND A.itemdcd = B.item4cd AND A.astate=C.statecd AND A.acorpcd=CONCAT(D.cocd, D.divcd)
AND itemdcd = #{itemdcd}
AND apart LIKE CONCAT('%',#{apart},'%')
AND acorpcd = #{acorpcd}
AND astate = #{astate}
AND lgubun = #{lgubun}
AND swno LIKE CONCAT('%',#{swno},'%')
ORDER BY swno DESC LIMIT #{number}, 19

mapper.update:
UPDATE sw_master
   SET itemdcd=#{itemdcd}, swnm=#{swnm}, mcorp=#{mcorp}, myear=#{myear}, ugubun=#{ugubun}, lgubun=#{lgubun}
     , lqty=#{lqty}, rqty=#{rqty}, lsdate=#{lsdate}, ledate=#{ledate}, astate=#{astate}, iyear=#{iyear}, price=#{price}
     , aplace=#{aplace}, apart=#{apart}, acorp=#{acorp}, auser=#{auser}, acorpcd=#{acorpcd}
     , regid=#{regid}, regip=#{regip}, regdt=NOW(), spec=#{spec}, attr1=#{attr1}, attr2=#{attr2}
 WHERE swno=#{swno}
